<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import {useApplicationSettings} from '../stores/settings';
import {useAgents} from '../stores/agents';import {useModelSettings} from '../stores/models';import {useOrganizer} from '../stores/organizer';
import {agents,type AgentConfig,type AgentId,type TrackerSampleTodo} from '../domain/agents';import {runError,mcpCloseWarning} from '../domain/organizer';import {displayPoint,displayTime} from '../domain/todos';import {usableModel,object} from '../domain/model-catalog';
import Icon from './Icon.vue';import SkField from './ui/SkField.vue';import SkSelect from './ui/SkSelect.vue';import SkTextarea from './ui/SkTextarea.vue';import SkButton from './ui/SkButton.vue';import SkFieldset from './ui/SkFieldset.vue';import SkSaveBar from './ui/SkSaveBar.vue';
const settings=useApplicationSettings();
const emit=defineEmits<{models:[]}>(),state=useAgents(),model=useModelSettings(),organizer=useOrganizer(),trialTab=ref<'sample'|'result'>('sample');
const row=computed(()=>state.current),role=computed(()=>agents.find(a=>a.id===state.selected)!),trial=computed(()=>state.trials[state.selected]),trialAgent=computed(()=>trial.value?.snapshot.agent as AgentConfig|undefined);
const trialModelName=computed(()=>{const m=trial.value?.snapshot.model as Record<string,unknown>|undefined;return String(m?.name||m?.apiModelId||trial.value?.snapshot.modelId||'');});
const trackerSample=computed(()=>(trial.value?.snapshot.trackerSample as {todos:TrackerSampleTodo[]}|undefined)?.todos||[]);
const changeLabels={progress:'进展线索',submission:'提交线索',acceptance:'验收线索',risk:'风险线索'};
const previewCount=computed(()=>trial.value?.roleResult?.suggestions.length??trial.value?.result?.length??0);
const options=computed(()=>[{value:0,label:`继承全局默认 · ${model.findModel(model.configuration?.defaultModelId||'')?.name||'尚未设置'}`,group:'跟随全局'},...(model.configuration?.models.models.filter(m=>usableModel(model.configuration,m.id)).map(m=>({value:m.id,label:m.name||m.apiModelId,description:m.apiModelId,group:model.findProvider(m.providerId)?.name||m.providerId}))||[]),...(row.value.draft.modelId&&!usableModel(model.configuration,row.value.draft.modelId)?[{value:row.value.draft.modelId,label:'已失效模型，请重新选择',group:'不可用',disabled:true}]:[])]);
const roleModel=computed({get:()=>row.value.draft.modelId??0,set:(value:string|number)=>row.value.draft.modelId=typeof value==='number'?null:value});
const toolsEnabled=computed(()=>object(model.findModel(row.value.draft.modelId||model.configuration?.defaultModelId||'')?.capabilities).toolCall!==false);
const changedSinceTrial=computed(()=>trial.value&&(trialAgent.value?.revision!==row.value.config?.revision||trial.value.snapshot.revision!==model.configuration?.revision));
const canTrial=computed(()=>settings.ready&&!settings.loading&&!settings.saving&&row.value.ready&&!row.value.loading&&!row.value.saving&&!state.dirty&&!state.running&&!state.starting&&!organizer.running&&!organizer.starting&&model.ready&&!!model.configuration&&!!state.sample.trim());
async function select(id:AgentId){try{await state.select(id);}catch{}}
async function save(){try{await state.save();}catch{}}
async function start(){if(!canTrial.value)return;try{await state.startTrial();trialTab.value='result';}catch{}}
async function cancel(){try{await state.cancelTrial();}catch{}}
onMounted(()=>{void select(state.selected);if(!model.ready)void model.load().catch(()=>{});});
</script>
<template><section class="agent-config-page"><div class="agent-role-tabs" role="group" aria-label="内置智能体"><button v-for="item in agents" :key="item.id" :class="{active:state.selected===item.id}" :aria-pressed="state.selected===item.id" :disabled="row.saving||state.starting" @click="select(item.id)"><Icon :name="item.id==='organizer'?'inbox':item.id==='tracker'?'refresh':'today'"/>{{item.name}}</button></div>
<div class="agent-config-grid"><section class="agent-config-form"><header class="agent-config-heading"><div><h2>{{role.name}}</h2><p>{{role.description}}</p></div><span>内置 · 职责固定</span></header><p v-if="row.loading" class="muted" role="status">正在读取配置…</p><div v-if="row.error" class="profile-alert" role="alert"><p>{{row.error}}</p><SkButton kind="entry" :disabled="row.loading||row.saving" @click="state.load(state.selected).catch(()=>{})">重新读取，保留草稿</SkButton></div><form @submit.prevent="save"><SkFieldset :disabled="!row.ready||row.loading||row.saving||state.starting"><SkField label="使用的模型"><SkSelect v-model="roleModel" :options="options" searchable/></SkField><div class="agent-model-hint"><button class="text-button" type="button" @click="emit('models')">{{model.configuration?'管理模型服务':'先配置默认模型'}}<Icon name="arrow"/></button></div><p v-if="model.error" class="form-error" role="alert">{{model.error}}</p><div class="form-grid"><SkField label="关注重点"><SkSelect v-model="row.draft.preferences.focus" :options="role.focus.map(([value,label])=>({value,label}))"/></SkField><SkField label="表达详略"><SkSelect v-model="row.draft.preferences.detail" :options="[{value:'concise',label:'简洁'},{value:'standard',label:'标准'},{value:'detailed',label:'详细'}]"/></SkField></div><SkField class="agent-instructions" label="补充说明"><template #action><small class="muted">{{row.draft.supplementalInstructions.length}} / 4000</small></template><SkTextarea v-model="row.draft.supplementalInstructions" rows="5" maxlength="4000" placeholder="补充工作习惯，不替换角色职责。"/></SkField><p class="agent-rules"><Icon name="check"/>原文依据、人工签收与正式状态规则保持固定。</p><button class="text-button agent-reset" type="button" @click="state.stageReset()">恢复当前角色默认</button></SkFieldset></form></section>
<aside class="agent-trial-pane" :aria-label="`${role.name}隔离试跑`"><header class="agent-trial-heading"><h3>隔离试跑</h3><div class="agent-trial-tabs"><button :class="{active:trialTab==='sample'}" :aria-pressed="trialTab==='sample'" @click="trialTab='sample'">样例</button><button :class="{active:trialTab==='result'}" :aria-pressed="trialTab==='result'" @click="trialTab='result'">结果</button></div></header>
<template v-if="state.selected!=='advisor'"><div v-if="trialTab==='sample'"><p v-if="state.selected==='tracker'" class="muted">只读关联两条固定合成事项：我整理接入清单、林川修复SDK鉴权，均尚未提交／验收。下方仅填写合成线索，不读取或修改正式事项，不使用工具。</p><p v-else class="muted">按已保存配置整理样例。{{toolsEnabled?'预览不进入待确认或正式事项；可按需读取已安装技能并使用 Read／Bash。':'当前模型未启用工具调用，试跑仅整理文本，不能验证 Skills。'}}</p><SkField :label="state.selected==='tracker'?'合成线索':'试跑文本'"><SkTextarea v-model="state.sample" rows="5" maxlength="64000" :disabled="state.starting||state.running"/></SkField><div class="agent-trial-actions"><small class="muted">{{state.dirty?'先保存左侧配置。':state.running?'正在试跑样例…':state.selected==='tracker'?'使用已保存配置与宿主固定样本。':'使用已保存配置与已发布技能索引。'}}</small><SkButton v-if="state.running" kind="quiet" @click="cancel">取消试跑</SkButton><SkButton v-else kind="entry" :disabled="!canTrial" :loading="state.starting" @click="start">开始隔离试跑</SkButton></div></div>
<div v-else class="trial-outcome"><p v-if="!trial" class="muted">保存配置后，先用样例查看只读预览。</p><template v-else><p v-if="trial.status==='running'||trial.status==='queued'" role="status">班班正在用这份配置理解样例… <button class="text-button" @click="cancel">取消试跑</button></p><p v-else-if="trial.status==='succeeded'" class="agent-trial-status" role="status">试跑完成，{{previewCount}}条预览；未新增正式事项。</p><p v-else class="form-error" role="alert">{{runError(trial)}}</p><p v-if="trial.status==='succeeded'&&mcpCloseWarning(trial)" class="muted">{{mcpCloseWarning(trial)}}</p><p v-if="changedSinceTrial" class="muted">结果对应先前保存的配置；请重新试跑查看新配置效果。</p><p v-if="state.dirty" class="muted">当前草稿尚未保存，已有结果不会随草稿改变。</p><p class="muted">{{displayTime(trial.createdAtMs)}} · {{trialModelName}}</p><template v-if="trial.roleResult?.kind==='tracker'"><p class="muted">以下均为建议预览，提交／验收线索不等于已确认完成。</p><p v-if="!trial.roleResult.suggestions.length" class="muted">本次没有发现可关联的变化。</p><ol class="agent-preview-list"><li v-for="(item,index) in trial.roleResult.suggestions" :key="index"><strong>{{trackerSample.find(todo=>todo.id===item.todoId)?.title||item.todoId}}</strong><p>{{changeLabels[item.change]}} · 样本版本 {{item.todoVersion}}</p><p>{{item.summary}}</p><details open><summary>线索原文依据</summary><blockquote>{{item.evidence}}</blockquote></details></li></ol></template><ol v-if="trial.result" class="agent-preview-list"><li v-for="(item,index) in trial.result" :key="index"><strong>{{item.fields.title}}</strong><p>{{item.fields.kind==='action'?'待我处理':'待我跟进'}} · {{item.fields.owner}} · 交付 {{item.fields.due?displayPoint(item.fields.due):'未定期'}}</p><p v-if="item.fields.kind==='followup'">跟进 {{item.fields.followup?displayPoint(item.fields.followup):'未定期'}}</p><p v-if="item.fields.tags.length"><span v-for="tag in item.fields.tags" :key="tag" class="pill">{{tag}}</span></p><details><summary>原文依据</summary><blockquote>{{item.evidence}}</blockquote></details><p v-for="warning in item.warnings" :key="warning" class="form-error">{{warning}}</p></li></ol><details class="agent-trial-snapshot"><summary>原文与本次设置</summary><pre>{{trial.input.text}}</pre><ul v-if="trackerSample.length"><li v-for="todo in trackerSample" :key="todo.id">{{todo.title}} · {{todo.owner}} · {{todo.submission}}／{{todo.acceptance}} · v{{todo.version}}</li></ul><p v-if="trialAgent" class="muted">{{role.focus.find(([value])=>value===trialAgent?.preferences.focus)?.[1]}} · {{trialAgent.preferences.detail==='concise'?'简洁':trialAgent.preferences.detail==='detailed'?'详细':'标准'}}<br>{{trialAgent.supplementalInstructions||'未补充说明'}}</p></details></template></div><p v-if="state.trialError" class="form-error" role="alert">{{state.trialError}} <button class="text-button" @click="state.refreshTrial">重新核对状态</button></p></template>
<div v-else class="agent-trial-unavailable"><h3>这个角色的试跑暂未开放</h3><p>模型和工作偏好可以先保存；真实进展跟踪与今日建议留后续阶段。</p></div></aside></div><SkSaveBar target="#settings-save-slot" :dirty="state.dirty" :busy="row.saving" :disabled="!row.ready||row.loading||state.starting" :error="row.error" :notice="row.notice" label="保存偏好" @save="save" @discard="state.discard"/>
</section></template>
